{
  "schemaVersion": 1,
  "id": "parker.screen-sleep",
  "name": "Screen sleep",
  "version": "1.0.0",
  "author": "parker",
  "description": "Turns displays off (DPMS) after 10 minutes without input and back on at the next mouse or keyboard input. Never suspends the machine.",
  "kinds": [
    "service"
  ],
  "entryPoints": {
    "service": "Service.qml"
